<?php $url = (string) ($_ENV['URL_ADM'] ?? ''); $perms = $this->data['buttonPermission'] ?? []; ?>
<div class="container-fluid px-4"><div class="d-flex justify-content-between align-items-center mt-4 mb-3"><h1 class="h3">Pontos de controle</h1><?php if (in_array('PortariaPontosCreate', $perms, true)): ?><a class="btn btn-success" href="<?= $url ?>portaria-pontos-create">Cadastrar ponto</a><?php endif; ?></div>
